class PriorityQueue:
    def __init__(self):
        self.queue = []

    def __str__(self):
        return ' '.join([str(i) for i in self.queue])

    # Function to insert elements into the queue
    def insert(self, data):
        self.queue.append(data)

    # Function to remove element from the queue
    def remove(self):
        try:
            min_index = 0
            for i in range(len(self.queue)):
                if self.queue[i][1] < self.queue[min_index][1]:
                    min_index = i
            item = self.queue[min_index]
            del self.queue[min_index]
            return item
        except IndexError:
            print("Priority Queue is empty.")
            return None

def find_path(graph, start, goal):
    # Priority queue to store (node, distance)
    pq = PriorityQueue()
    pq.insert((start, 0))
    visited = set()

