from collections import defaultdict, deque

def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None

    # Initialize the priority queue with the start node.
    # Priority is determined by the number of unexplored neighbors (neighbors not visited yet).
    priority_queue = [(0, start)]
    visited = set()
    parent = {start: None}
    distances = {node: float('inf') for node in graph}
    distances[start] = 0

    while priority_queue:
        # Pop the node with the lowest priority (fewest unexplored neighbors).
        current_distance, current_node = min(priority_queue, key=lambda x: x[0])

        if current_node == goal:
            path = []
            while current_node is not None:
                path.append(current_node)
                current_node = parent[current_node]
            return path[::-1]  # Reverse the path to get it in start-to-goal order.

        visited.add(current_node)
        priority_queue.remove((current_distance, current_node))

        for neighbor in graph[current_node]:
            if neighbor in visited:
                continue
            if distances[neighbor] > current_distance + 1:
                distances[neighbor] = current_distance + 1
                priority_queue.append((distances[neighbor], neighbor))
                parent[neighbor] = current_node

    return None

