        if path is None:
            path = [start]
        if start == goal:
            return path
        for neighbor in graph.get(start, []):
            if neighbor not in path:
                new_path = dfs_search(graph, neighbor, goal, path + [neighbor])
                if new_path:
                    return new_path
        return None

    # Breadth-First Search (BFS) implementation
    def bfs_search(graph, start, goal):
        queue = [[start]]
        while queue:
            path = queue.pop(0)
            node = path[-1]
            if node == goal:
                return path
            for neighbor in graph.get(node, []):
                if neighbor not in path:
                    new_path = list(path)
                    new_path.append(neighbor)
                    queue.append(new_path)
        return None

    # Calling the DFS function to find the path
    dfs_result = dfs_search(graph, start, goal)
    bfs_result = bfs_search(graph, start, goal)

