                came_from_start[neighbor] = current_start
                g_score_start[neighbor] = tentative_g_score_start
                f_score_start[neighbor] = tentative_g_score_start + heuristic(neighbor, goal)
                if neighbor not in open_set_start:
                    heapq.heappush(open_set_start, (f_score_start[neighbor], neighbor))

        for neighbor in graph[current_goal]:
            tentative_g_score_goal = g_score_goal[current_goal] + 1
            if neighbor not in g_score_goal or tentative_g_score_goal < g_score_goal[neighbor]:
                came_from_goal[neighbor] = current_goal
                g_score_goal[neighbor] = tentative_g_score_goal
                f_score_goal[neighbor] = tentative_g_score_goal + heuristic(neighbor, start)
                if neighbor not in open_set_goal:
                    heapq.heappush(open_set_goal, (f_score_goal[neighbor], neighbor))

    return None

